--
-- Table structure for table `ucla_health_forms`
--

DROP TABLE IF EXISTS `ucla_health_forms`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ucla_health_forms` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `first_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `last_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `gender` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `birthdate` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `physical_restrictions` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `known_allergies` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `allergies_note` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `diet_nutrition` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `diet_note` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `diptheira_tetanus_pertussis_date` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `polio_date` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tetanus_booster_date` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `haemophilus_influenza_date` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mumps_measles_rubella_date` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pneumococcal_date` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hepatitis_b_date` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hepatitis_a_date` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chicken_pox_date` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meningococcal_meningitis_date` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sign_of_custodial_parent` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `custodial_parent_relationship` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `custodial_parent_date` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `non_prescription_medicine` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `prescription_medicine` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `medicine_to_not_be_given` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `general_health_history` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mental_emotional_health` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `help_friendship_note` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `anxiety_note` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mental_health_note` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `behavioral_note` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `parent_first_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `parent_last_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `authorization_date` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `relation_to_camper` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `additional_comments` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `require_transportation` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `agree_terms_conditions_parent_first_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `agree_terms_conditions_parent_last_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `agree_changes_parent_first_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `agree_changes_parent_last_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=133 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

